<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useStaffWallet} from '../wallet/useStaffWallet'
import {cardApi} from './api'
import {useCardText} from './text'
import {money,displayName} from './format'
import type {Purchase} from './types'
const props=defineProps<{store:string;orders:Purchase[];disabled:boolean;can:(p:string)=>boolean}>(),emit=defineEmits<{changed:[];error:[message:string]}>(),{t,locale}=useCardText(),selected=ref(''),busy=ref(false)
const {context}=useStaffWallet();const channels=computed(()=>context.value?.program?.channels??[])
const form=ref({channel:'cash',account:'',terminal:'T1',receipt:'',verified:false,reason:''})
watch(channels,list=>{if(!list.includes(form.value.channel))form.value.channel=list[0]??''},{immediate:true})
async function act(order:Purchase,refund=false){busy.value=true;const store=props.store;try{await cardApi(store).command(`/purchases/${order.id}/${refund?'refund':'confirm'}`,refund?{reason:form.value.reason,receipt:form.value.receipt,verified:form.value.verified}:{...form.value,amountCents:order.amountCents},refund?'purchase.refund':'purchase.confirm');selected.value='';form.value.receipt='';form.value.verified=false;if(store===props.store)emit('changed')}catch(e){if(store===props.store)emit('error',String(e))}finally{busy.value=false}}
async function exception(order:Purchase){busy.value=true;try{await cardApi(props.store).command(`/purchases/${order.id}/exception`,{payment:{...form.value,amountCents:order.amountCents},reason:form.value.reason},'purchase.exception');selected.value='';emit('changed')}catch(e){emit('error',String(e))}finally{busy.value=false}}
</script>
<template><section class="cards-panel"><h2>{{t('purchases')}}</h2><p class="cards-notice">{{t('policy')}}</p><p v-if="!orders.length">{{t('empty')}}</p><article v-for="o in orders" :key="o.id" class="cards-panel"><div class="cards-actions"><strong>{{displayName(o.snapshot,locale)}}</strong><span>{{money(o.amountCents)}}</span><span class="cards-badge">{{t(o.status)}}</span></div><small>{{o.id}} · {{t('customer')}} {{o.customerId.slice(0,8)}}</small><button v-if="(o.status==='pending'&&can('wallet.cards.sell'))||(['issued','exception'].includes(o.status)&&can('wallet.cards.refund'))" :disabled="disabled||busy" @click="selected=selected===o.id?'':o.id">{{t(o.status==='pending'?'payment':'refund')}}</button><form v-if="selected===o.id" @submit.prevent="act(o,o.status==='issued'||o.status==='exception')"><p v-if="o.status!=='pending'" class="cards-notice">{{t('refundHint')}}</p><div class="cards-grid"><template v-if="o.status==='pending'"><label>{{t('channel')}}<select v-model="form.channel"><option v-for="channel in channels" :key="channel" :value="channel">{{context?.program?.channelLabels?.[channel]||channel.split(':')[0]}}</option></select></label><label>{{t('account')}}<input v-model="form.account"></label><label>{{t('terminal')}}<input v-model="form.terminal" required></label></template><label>{{t('receipt')}}<input v-model="form.receipt" maxlength="100" required></label><label>{{t('reason')}}<input v-model="form.reason" :required="o.status!=='pending'"></label></div><label class="check"><input v-model="form.verified" type="checkbox" required>{{t('verified')}}</label><button class="primary" :disabled="busy||disabled||!form.verified">{{t('confirm')}}</button><button v-if="o.status==='pending'&&can('wallet.cards.refund')" type="button" :disabled="busy||disabled||!form.verified||!form.reason||!form.receipt" @click="exception(o)">{{t('recordException')}}</button><p v-if="o.status==='pending'&&can('wallet.cards.refund')" class="cards-muted">{{t('exceptionHint')}}</p></form></article></section></template>
